<?php declare(strict_types=1);session_start();if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$tienda=(int)($_POST['tienda_id']??0);$cat=(int)($_POST['categoria_id']??0);$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('UPDATE tiendas SET galeria_categoria_id=? WHERE id=?');$q->execute([$cat,$tienda]);header('Location: galeria-categorias-admin.php?assigned=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo asignar la tienda.');}
